<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { api, session, errorText } from '../api';
import AtlasIcon from '../components/AtlasIcon.vue';
import type { AccountSummary, Visit } from '../../../packages/contracts/src/index.js';
const busy = ref(false), error = ref('');
const summary = ref<AccountSummary | null>(null), visits = ref<Visit[]>([]);
onMounted(async () => { try { [summary.value, visits.value] = await Promise.all([api<AccountSummary>('/me/summary'), api<Visit[]>('/visits')]); } catch (e) { error.value = errorText(e); } });
async function removeVisit(visit: Visit) { if (!window.confirm(`取消“${visit.label}”的到访确认？行程与日记会保留。`)) return; busy.value = true; try { await api('/visits/' + visit.id, 'DELETE', { clientMutationId: crypto.randomUUID() }); visits.value = visits.value.filter(v => v.id !== visit.id); summary.value = await api<AccountSummary>('/me/summary'); } catch (e) { error.value = errorText(e); } finally { busy.value = false; } }
async function logout() { busy.value = true; try { await api('/auth/logout', 'POST'); session.value = null; } catch (e) { error.value = errorText(e); } finally { busy.value = false; } }
</script>
<template><section class="flow-view"><div class="flow-scroll"><header class="flow-header"><p class="eyebrow">A LITTLE SPACE OF YOUR OWN</p><h2>我的旅行簿</h2><p>留住沿途，也给下一程留一点期待。</p></header><div class="profile-mark"><AtlasIcon name="user" :size="32"/></div><h3>{{ session?.user.displayName }}</h3><p class="muted">{{ session?.user.username }}</p><div v-if="summary" class="profile-counts"><div><strong>{{ summary.journeys }}</strong><span>次旅程</span></div><div><strong>{{ summary.diaries }}</strong><span>篇日记</span></div><div><strong>{{ summary.visits }}</strong><span>条到访确认</span></div></div><p v-if="summary" class="small muted">照片占用 {{ (summary.mediaBytes / 1048576).toFixed(1) }} MB / {{ Math.round(summary.mediaQuotaBytes / 1048576) }} MB，含私密原图与预览。</p><div class="profile-note"><AtlasIcon name="lock"/><p>旅程、日记与照片仅自己可见。到访数来自你主动确认的记录，不代表去重城市或实际轨迹统计。</p></div><details v-if="visits.length" class="profile-visits"><summary>已确认到访 · 最近 {{ visits.length }} 条</summary><article v-for="visit in visits" :key="visit.id" class="visit-row"><div class="od-fill"><strong>{{ visit.label }}</strong><small>{{ visit.visitedOn }} · {{ visit.region || '地区未填写' }}</small><p v-if="visit.detached">原地点已从路线移除，此次到访仍保留。</p><p v-if="visit.note">{{ visit.note }}</p></div><button class="text-button" :disabled="busy" @click="removeVisit(visit)">取消确认</button></article></details><p v-if="error" class="flow-form-errors" role="alert">{{ error }}</p><button class="secondary-button full" :disabled="busy" @click="logout">{{ busy ? '正在处理…' : '退出登录' }}</button></div></section></template>
